pub fn enqueue_localization_batch_v1(
    paths: &AppPaths,
    request: LocalizationBatchRequest,
) -> Result<LocalizationBatchQueueSummary> {
    let item_ids = normalize_localization_batch_item_ids(request.item_ids)?;
    if item_ids.is_empty() {
        return Err(EngineError::InstallFailed(
            "choose at least one item for batch dubbing".to_string(),
        ));
    }
    let batch_id = Uuid::new_v4().to_string();
    let mut items: Vec<LocalizationBatchItemResult> = Vec::new();
    let separation_backend = normalize_separation_backend(request.separation_backend.as_deref());

    for item_id in item_ids {
        let item = library::get_item_by_id(paths, &item_id)?;
        let mut warnings: Vec<String> = Vec::new();
        let mut applied_mapping_count = 0usize;
        let selected_track = select_localization_batch_track(paths, &item_id)?;
        let track = match selected_track {
            Some(track) => track,
            None => {
                items.push(LocalizationBatchItemResult {
                    item_id: item_id.clone(),
                    title: item.title.clone(),
                    track_id: None,
                    applied_mapping_count,
                    warnings: vec!["No subtitle track found for this item.".to_string()],
                    queued_jobs: Vec::new(),
                });
                continue;
            }
        };

        let current_speakers = subtitle_tracks::load_document(paths, &track.id)?
            .segments
            .into_iter()
            .filter_map(|segment| segment.speaker)
            .map(|speaker| speaker.trim().to_string())
            .filter(|speaker| !speaker.is_empty())
            .collect::<HashSet<_>>();

        if let Some(template_id) = request.template_id.as_deref() {
            let mappings =
                auto_match_template_speakers(paths, template_id, &item_id, &current_speakers)?;
            if mappings.is_empty() {
                warnings.push(
                    "Template selected, but no speakers auto-matched on this item.".to_string(),
                );
            } else {
                applied_mapping_count += mappings.len();
                let _ = voice_templates::apply_voice_template_to_item(
                    paths,
                    &item_id,
                    template_id,
                    &mappings,
                    request.cast_pack_id.is_none(),
                )?;
            }
        }

        if let Some(pack_id) = request.cast_pack_id.as_deref() {
            let mappings = auto_match_cast_pack_roles(paths, pack_id, &item_id, &current_speakers)?;
            if mappings.is_empty() {
                warnings.push(
                    "Cast pack selected, but no roles auto-matched on this item.".to_string(),
                );
            } else {
                applied_mapping_count += mappings.len();
                let _ = voice_cast_packs::apply_voice_cast_pack_to_item(
                    paths, &item_id, pack_id, &mappings, true,
                )?;
            }
        }

        let pipeline = LocalizationPipelineOptions {
            auto_pipeline: true,
            output_mode: Some("dub".to_string()),
            source_track_id: Some(track.id.clone()),
            separation_backend: separation_backend.clone(),
            queue_export_pack: request.queue_export_pack,
            queue_qc: request.queue_qc,
            variant_label: None,
            tts_backend_id: Some(default_dub_backend_id(paths)),
            speaker_overrides: Vec::new(),
            speaker_count: DiarizationSpeakerCountRequest::default(),
        };

        let outcome = queue_localization_continuation_from_track(
            paths,
            &item,
            &track,
            pipeline.clone(),
            Some(batch_id.clone()),
        )?;
        let queued_jobs = outcome.queued_jobs;
        // WP-0262: make a voice-reference-blocked outcome visible up front in the batch summary
        // instead of leaving the operator with only a soft note that nothing was queued.
        if outcome.voice_reference_blocked {
            warnings.push(VOICE_REFERENCE_BLOCKED_MESSAGE.to_string());
        }
        if queued_jobs.is_empty() && !outcome.notes.is_empty() {
            warnings.extend(outcome.notes);
        }

        items.push(LocalizationBatchItemResult {
            item_id,
            title: item.title,
            track_id: Some(track.id),
            applied_mapping_count,
            warnings,
            queued_jobs,
        });
    }

    let queued_jobs_total = items.iter().map(|item| item.queued_jobs.len()).sum();
    Ok(LocalizationBatchQueueSummary {
        batch_id,
        queued_jobs_total,
        items,
    })
}

fn track_speaker_keys(paths: &AppPaths, track_id: &str) -> Result<Vec<String>> {
    let doc = subtitle_tracks::load_document(paths, track_id)?;
    let mut speakers = doc
        .segments
        .iter()
        .filter_map(|segment| segment.speaker.as_ref())
        .map(|speaker| speaker.trim().to_string())
        .filter(|speaker| !speaker.is_empty())
        .collect::<Vec<_>>();
    speakers.sort();
    speakers.dedup();
    Ok(speakers)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SubtitleDocumentSegmentStats {
    raw_segment_count: usize,
    usable_segment_count: usize,
}

fn subtitle_document_segment_stats(
    doc: &subtitles::SubtitleDocument,
) -> SubtitleDocumentSegmentStats {
    SubtitleDocumentSegmentStats {
        raw_segment_count: doc.segments.len(),
        usable_segment_count: subtitles::usable_segment_count(doc),
    }
}

fn empty_transcript_reason(raw_segment_count: usize, usable_segment_count: usize) -> &'static str {
    if raw_segment_count == 0 {
        "no_speech_detected"
    } else if usable_segment_count == 0 {
        "all_segments_empty_after_filtering"
    } else {
        "usable_segments_present"
    }
}

fn empty_transcript_error_message(
    stage_label: &str,
    raw_segment_count: usize,
    usable_segment_count: usize,
    media_path: &str,
) -> String {
    let reason = empty_transcript_reason(raw_segment_count, usable_segment_count);
    format!(
        "{stage_label} produced no usable subtitle segments ({reason}; raw segments: {raw_segment_count}; usable segments: {usable_segment_count}; media: {media_path}). No downstream localization stages were queued."
    )
}

// WP-0262: plain operator-facing message used when the multi-speaker localization pipeline could
// not build a per-speaker voice reference and therefore queued nothing. Surfaced as a VISIBLE
// terminal job failure so the operator is not left staring at a silently stalled item.
const VOICE_REFERENCE_BLOCKED_MESSAGE: &str =
    "Couldn't build a voice reference for one or more speakers - try single-speaker or add a reference";

// WP-0262: build the operator-facing message for a voice-reference-blocked continuation outcome,
// appending the pipeline notes (which name the affected speakers) when available.
fn voice_reference_blocked_message(notes: &[String]) -> String {
    let mut message = VOICE_REFERENCE_BLOCKED_MESSAGE.to_string();
    let detail = notes
        .iter()
        .map(|note| note.trim())
        .filter(|note| !note.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    if !detail.is_empty() {
        message.push_str(" (");
        message.push_str(&detail);
        message.push(')');
    }
    message
}

fn empty_track_stage(track: &subtitle_tracks::SubtitleTrackRow) -> String {
    match track.kind.as_str() {
        "source" => "empty_source_track".to_string(),
        "translated" => "empty_translation_track".to_string(),
        other => format!("empty_{other}_track"),
    }
}

fn empty_track_continuation_outcome(
    track: &subtitle_tracks::SubtitleTrackRow,
    stats: SubtitleDocumentSegmentStats,
) -> LocalizationContinuationOutcome {
    let stage = empty_track_stage(track);
    LocalizationContinuationOutcome {
        stage,
        source_track_id: if track.kind == "source" {
            Some(track.id.clone())
        } else {
            None
        },
        translated_track_id: if track.kind == "translated" {
            Some(track.id.clone())
        } else {
            None
        },
        queued_jobs: Vec::new(),
        notes: vec![format!(
            "The {} track contains no usable subtitle segments ({}; raw segments: {}; usable segments: {}). Re-run the failed prerequisite stage before continuing localization.",
            track.kind,
            empty_transcript_reason(stats.raw_segment_count, stats.usable_segment_count),
            stats.raw_segment_count,
            stats.usable_segment_count
        )],
        ..Default::default()
    }
}

fn missing_voice_plan_speakers(
    paths: &AppPaths,
    item_id: &str,
    track_id: &str,
) -> Result<Vec<String>> {
    let speakers = track_speaker_keys(paths, track_id)?;
    if speakers.is_empty() {
        return Ok(Vec::new());
    }

    let settings = speaker_render_settings_by_key(paths, item_id)?;
    let mut missing = Vec::new();
    for speaker_key in speakers {
        let setting = settings.get(&speaker_key).cloned().unwrap_or_default();
        if setting.render_mode.as_deref() == Some("standard_tts") {
            continue;
        }
        let has_profile = !setting.profile_paths.is_empty()
            || setting
                .primary_profile_path
                .as_deref()
                .map(str::trim)
                .is_some_and(|value| !value.is_empty());
        if !has_profile {
            missing.push(speaker_key);
        }
    }
    Ok(missing)
}

fn decide_localization_next_stage(
    paths: &AppPaths,
    item_id: &str,
    track: &subtitle_tracks::SubtitleTrackRow,
) -> Result<LocalizationNextStageDecision> {
    if track.kind == "source" {
        return Ok(LocalizationNextStageDecision::Translate);
    }

    if track.kind == "translated" && normalize_lang_tag(Some(&track.lang)) == Some("eng") {
        let speakers = track_speaker_keys(paths, &track.id)?;
        if speakers.is_empty() {
            return Ok(LocalizationNextStageDecision::Diarize);
        }
        let missing = missing_voice_plan_speakers(paths, item_id, &track.id)?;
        if !missing.is_empty() {
            return Ok(LocalizationNextStageDecision::VoicePlanBlocked {
                missing_speakers: missing,
            });
        }
        return Ok(LocalizationNextStageDecision::Dub);
    }

    Ok(LocalizationNextStageDecision::Translate)
}

fn localization_output_mode(raw: Option<&str>) -> Result<String> {
    let value = raw
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("dub")
        .to_lowercase();
    match value.as_str() {
        "dub" | "subtitles" => Ok(value),
        _ => Err(EngineError::InstallFailed(format!(
            "unsupported localization output mode: {value}"
        ))),
    }
}

fn clamp_diarization_speaker_count(raw: Option<u32>) -> Option<u32> {
    raw.filter(|value| *value > 0)
        .map(|value| value.min(DIARIZATION_SPEAKER_COUNT_MAX))
}

fn normalize_diarization_speaker_count(
    request: &DiarizationSpeakerCountRequest,
) -> Result<NormalizedDiarizationSpeakerCount> {
    let mode = request
        .mode
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("auto")
        .to_lowercase();

    match mode.as_str() {
        "auto" => Ok(NormalizedDiarizationSpeakerCount {
            mode,
            exact_speakers: None,
            min_speakers: None,
            max_speakers: None,
        }),
        "exact" => Ok(NormalizedDiarizationSpeakerCount {
            mode,
            exact_speakers: Some(
                clamp_diarization_speaker_count(request.exact_speakers).unwrap_or(2),
            ),
            min_speakers: None,
            max_speakers: None,
        }),
        "range" => {
            let mut min_speakers =
                clamp_diarization_speaker_count(request.min_speakers).unwrap_or(2);
            let mut max_speakers =
                clamp_diarization_speaker_count(request.max_speakers).unwrap_or(4);
            if min_speakers > max_speakers {
                std::mem::swap(&mut min_speakers, &mut max_speakers);
            }
            Ok(NormalizedDiarizationSpeakerCount {
                mode,
                exact_speakers: None,
                min_speakers: Some(min_speakers),
                max_speakers: Some(max_speakers),
            })
        }
        other => Err(EngineError::InstallFailed(format!(
            "unsupported diarization speaker count mode: {other}"
        ))),
    }
}

fn diarization_speaker_count_filename_suffix(
    speaker_count: &NormalizedDiarizationSpeakerCount,
) -> String {
    match speaker_count.mode.as_str() {
        "exact" => speaker_count
            .exact_speakers
            .map(|value| format!(".exact-{value}"))
            .unwrap_or_default(),
        "range" => match (speaker_count.min_speakers, speaker_count.max_speakers) {
            (Some(min_speakers), Some(max_speakers)) => {
                format!(".range-{min_speakers}-{max_speakers}")
            }
            _ => String::new(),
        },
        _ => String::new(),
    }
}

fn effective_diarization_speaker_count_request(
    params: &DiarizeLocalV1Params,
) -> DiarizationSpeakerCountRequest {
    if params.speaker_count.has_operator_value() {
        return params.speaker_count.clone();
    }
    params
        .pipeline
        .as_ref()
        .map(|pipeline| pipeline.speaker_count.clone())
        .unwrap_or_default()
}

#[derive(Debug, Clone, Default)]
struct AutoVoiceReferenceOutcome {
    applied_speakers: Vec<String>,
    failed_speakers: Vec<String>,
    notes: Vec<String>,
}

fn auto_apply_source_voice_references_for_missing_speakers(
    paths: &AppPaths,
    item_id: &str,
    track_id: &str,
    missing_speakers: &[String],
) -> AutoVoiceReferenceOutcome {
    let mut outcome = AutoVoiceReferenceOutcome::default();
    for speaker_key in missing_speakers {
        let speaker_key = speaker_key.trim();
        if speaker_key.is_empty() {
            continue;
        }
        match voice_reference_candidates::generate_reference_candidates(
            paths,
            voice_reference_candidates::VoiceReferenceCandidateGenerationRequest {
                item_id: item_id.to_string(),
                track_id: Some(track_id.to_string()),
                speaker_key: Some(speaker_key.to_string()),
                missing_only: true,
            },
        ) {
            Ok(report) => {
                let bundle = report
                    .bundles
                    .iter()
                    .find(|bundle| bundle.speaker_key == speaker_key);
                if !bundle
                    .map(|bundle| bundle.candidate_exists)
                    .unwrap_or(false)
                {
                    outcome.failed_speakers.push(speaker_key.to_string());
                    outcome.notes.push(format!(
                        "Source voice-reference generation did not produce a usable sample for {speaker_key}."
                    ));
                    continue;
                }
                match voice_reference_candidates::apply_reference_candidate(
                    paths,
                    item_id,
                    speaker_key,
                    "append",
                ) {
                    Ok(_) => {
                        outcome.applied_speakers.push(speaker_key.to_string());
                        if let Some(bundle) = bundle {
                            outcome.notes.push(format!(
                                "Generated and attached a source voice sample for {speaker_key} ({} clip(s), {} ms).",
                                bundle.clip_count, bundle.total_duration_ms
                            ));
                        } else {
                            outcome.notes.push(format!(
                                "Generated and attached a source voice sample for {speaker_key}."
                            ));
                        }
                    }
                    Err(err) => {
                        outcome.failed_speakers.push(speaker_key.to_string());
                        outcome.notes.push(format!(
                            "Generated a source voice sample for {speaker_key}, but applying it failed: {err}."
                        ));
                    }
                }
            }
            Err(err) => {
                outcome.failed_speakers.push(speaker_key.to_string());
                outcome.notes.push(format!(
                    "Source voice-reference generation failed for {speaker_key}: {err}."
                ));
            }
        }
    }
    outcome
}

fn localization_resume_request_for_dub(
    item_id: &str,
    pipeline: &LocalizationPipelineOptions,
) -> LocalizationRunRequest {
    LocalizationRunRequest {
        item_id: item_id.to_string(),
        asr_lang: None,
        separation_backend: pipeline.separation_backend.clone(),
        output_mode: Some("dub".to_string()),
        queue_export_pack: pipeline.queue_export_pack,
        queue_qc: pipeline.queue_qc,
        speaker_count: pipeline.speaker_count.clone(),
    }
}

fn queue_voice_setup_for_localization(
    paths: &AppPaths,
    item: &library::LibraryItem,
    track: &subtitle_tracks::SubtitleTrackRow,
    pipeline: &LocalizationPipelineOptions,
    batch_id: Option<String>,
    source_track_id: Option<String>,
    translated_track_id: Option<String>,
    mut notes: Vec<String>,
) -> Result<LocalizationContinuationOutcome> {
    let params_json = serde_json::to_string(&InstallPhase2PacksV1Params {
        resume_localization_run: Some(localization_resume_request_for_dub(&item.id, pipeline)),
    })?;
    let queued_job = enqueue_with_type_item_and_batch_id(
        paths,
        JobType::InstallPhase2PacksV1,
        params_json,
        Some(item.id.clone()),
        batch_id,
    )?;
    notes.push(
        "Voice cloning needs a one-time setup. VoxVulgi queued it and will continue this localization run automatically when setup finishes."
            .to_string(),
    );
    Ok(LocalizationContinuationOutcome {
        stage: "voice_setup".to_string(),
        source_track_id,
        translated_track_id: translated_track_id.or_else(|| Some(track.id.clone())),
        queued_jobs: vec![queued_job],
        notes,
        ..Default::default()
    })
}

fn queue_dub_or_voice_setup_for_localization(
    paths: &AppPaths,
    item: &library::LibraryItem,
    track: &subtitle_tracks::SubtitleTrackRow,
    pipeline: LocalizationPipelineOptions,
    batch_id: Option<String>,
    source_track_id: Option<String>,
    translated_track_id: Option<String>,
    mut notes: Vec<String>,
) -> Result<LocalizationContinuationOutcome> {
    let pack = tools::tts_voice_preserving_local_v1_pack_status(paths);
    if !pack.installed {
        return queue_voice_setup_for_localization(
            paths,
            item,
            track,
            &pipeline,
            batch_id,
            source_track_id,
            translated_track_id,
            notes,
        );
    }

    let params_json = serde_json::to_string(&DubVoicePreservingV1Params {
        item_id: item.id.clone(),
        source_track_id: track.id.clone(),
        batch_on_import: false,
        pipeline: Some(LocalizationPipelineOptions {
            source_track_id: Some(track.id.clone()),
            ..pipeline
        }),
    })?;
    let queued_job = enqueue_with_type_item_and_batch_id(
        paths,
        JobType::DubVoicePreservingV1,
        params_json,
        Some(item.id.clone()),
        batch_id,
    )?;
    notes.push("VoxVulgi queued the dubbing pipeline.".to_string());
    Ok(LocalizationContinuationOutcome {
        stage: "dub".to_string(),
        source_track_id,
        translated_track_id: translated_track_id.or_else(|| Some(track.id.clone())),
        queued_jobs: vec![queued_job],
        notes,
        ..Default::default()
    })
}

fn queue_localization_continuation_from_track(
    paths: &AppPaths,
    item: &library::LibraryItem,
    track: &subtitle_tracks::SubtitleTrackRow,
    pipeline: LocalizationPipelineOptions,
    batch_id: Option<String>,
) -> Result<LocalizationContinuationOutcome> {
    let source_track_id = if track.kind == "source" {
        Some(track.id.clone())
    } else {
        latest_source_track(paths, &item.id)?.map(|value| value.id)
    };
    let translated_track_id =
        if track.kind == "translated" && normalize_lang_tag(Some(&track.lang)) == Some("eng") {
            Some(track.id.clone())
        } else {
            latest_translated_english_track(paths, &item.id)?.map(|value| value.id)
        };
    let track_doc = subtitle_tracks::load_document(paths, &track.id)?;
    let track_stats = subtitle_document_segment_stats(&track_doc);
    if track_stats.usable_segment_count == 0 {
        return Ok(empty_track_continuation_outcome(track, track_stats));
    }

    let output_mode = localization_output_mode(pipeline.output_mode.as_deref())?;
    if output_mode == "subtitles"
        && track.kind == "translated"
        && normalize_lang_tag(Some(&track.lang)) == Some("eng")
    {
        return Ok(LocalizationContinuationOutcome {
            stage: "subtitles".to_string(),
            source_track_id,
            translated_track_id: Some(track.id.clone()),
            queued_jobs: Vec::new(),
            notes: vec![
                "English subtitles are ready; no dubbing stages were requested.".to_string(),
            ],
            ..Default::default()
        });
    }

    match decide_localization_next_stage(paths, &item.id, track)? {
        LocalizationNextStageDecision::Translate => {
            let params_json = serde_json::to_string(&TranslateLocalParams {
                item_id: item.id.clone(),
                source_track_id: track.id.clone(),
                model_id: paths.effective_asr_model_id(),
                batch_on_import: false,
                pipeline: Some(LocalizationPipelineOptions {
                    source_track_id: Some(track.id.clone()),
                    ..pipeline
                }),
            })?;
            let queued_job = enqueue_with_type_item_and_batch_id(
                paths,
                JobType::TranslateLocal,
                params_json,
                Some(item.id.clone()),
                batch_id,
            )?;
            Ok(LocalizationContinuationOutcome {
                stage: "translate".to_string(),
                source_track_id: Some(track.id.clone()),
                translated_track_id,
                queued_jobs: vec![queued_job],
                notes: vec![
                    "No translated English track was available, so VoxVulgi queued translation first."
                        .to_string(),
                ],
                ..Default::default()
            })
        }
        LocalizationNextStageDecision::Diarize => {
            let params_json = serde_json::to_string(&DiarizeLocalV1Params {
                item_id: item.id.clone(),
                source_track_id: track.id.clone(),
                backend: None,
                speaker_count: pipeline.speaker_count.clone(),
                batch_on_import: false,
                pipeline: Some(LocalizationPipelineOptions {
                    source_track_id: Some(track.id.clone()),
                    ..pipeline
                }),
            })?;
            let queued_job = enqueue_with_type_item_and_batch_id(
                paths,
                JobType::DiarizeLocalV1,
                params_json,
                Some(item.id.clone()),
                batch_id,
            )?;
            Ok(LocalizationContinuationOutcome {
                stage: "diarize".to_string(),
                source_track_id,
                translated_track_id: Some(track.id.clone()),
                queued_jobs: vec![queued_job],
                notes: vec![
                    "The translated English track has no speaker labels yet, so VoxVulgi queued diarization before voice planning."
                        .to_string(),
                ],
                ..Default::default()
            })
        }
        LocalizationNextStageDecision::VoicePlanBlocked { missing_speakers } => {
            let mut notes = Vec::new();
            // WP-0262: when the auto dubbing pipeline exhausts its automatic attempt to build a
            // per-speaker voice reference and still cannot proceed, this is a terminal blocked
            // state (nothing was queued). Flag it so the job consumers surface a VISIBLE terminal
            // job/item state instead of silently doing nothing.
            let mut voice_reference_blocked = false;
            if pipeline.auto_pipeline && output_mode == "dub" {
                let auto_refs = auto_apply_source_voice_references_for_missing_speakers(
                    paths,
                    &item.id,
                    &track.id,
                    &missing_speakers,
                );
                notes.extend(auto_refs.notes);
                let still_missing = missing_voice_plan_speakers(paths, &item.id, &track.id)?;
                if still_missing.is_empty() {
                    if auto_refs.applied_speakers.is_empty() {
                        notes.push(
                            "Voice references are ready, so VoxVulgi can start the dubbing pipeline."
                                .to_string(),
                        );
                    } else {
                        notes.push(format!(
                            "Source voice samples are ready for {}; VoxVulgi can start the dubbing pipeline.",
                            auto_refs.applied_speakers.join(", ")
                        ));
                    }
                    return queue_dub_or_voice_setup_for_localization(
                        paths,
                        item,
                        track,
                        pipeline,
                        batch_id,
                        source_track_id,
                        Some(track.id.clone()),
                        notes,
                    );
                }
                // Auto attempt could not build usable per-speaker references -> terminal blocked.
                voice_reference_blocked = true;
                notes.push(format!(
                    "Voice-preserving dubbing still needs usable source voice samples for: {}.",
                    still_missing.join(", ")
                ));
                if !auto_refs.failed_speakers.is_empty() {
                    notes.push(format!(
                        "Automatic source-reference generation failed for: {}.",
                        auto_refs.failed_speakers.join(", ")
                    ));
                }
            } else {
                notes.push(format!(
                    "Voice-preserving dubbing is waiting for speaker references or Standard TTS routing for: {}.",
                    missing_speakers.join(", ")
                ));
            }
            Ok(LocalizationContinuationOutcome {
                stage: "voice_plan".to_string(),
                source_track_id,
                translated_track_id: Some(track.id.clone()),
                queued_jobs: Vec::new(),
                notes,
                voice_reference_blocked,
            })
        }
        LocalizationNextStageDecision::Dub => {
            queue_dub_or_voice_setup_for_localization(
                paths,
                item,
                track,
                pipeline,
                batch_id,
                source_track_id,
                Some(track.id.clone()),
                vec![
                    "Translated English track and speaker voice plan are ready for dubbing."
                        .to_string(),
                    "Mix will use a separated background when available, otherwise it will fall back to the source-audio review path."
                        .to_string(),
                ],
            )
        }
    }
}

pub fn enqueue_localization_run_v1(
    paths: &AppPaths,
    request: LocalizationRunRequest,
) -> Result<LocalizationRunQueueSummary> {
    let item_id = request.item_id.trim().to_string();
    if item_id.is_empty() {
        return Err(EngineError::InstallFailed(
            "item_id is required".to_string(),
        ));
    }
    let item = library::get_item_by_id(paths, &item_id)?;
    let batch_id = Uuid::new_v4().to_string();
    let source_track = latest_source_track(paths, &item_id)?;
    let translated_track = latest_translated_english_track(paths, &item_id)?;
    let lang = request
        .asr_lang
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty() && *value != "auto")
        .map(|value| value.to_string());
    let pipeline = LocalizationPipelineOptions {
        auto_pipeline: true,
        output_mode: Some(localization_output_mode(request.output_mode.as_deref())?),
        source_track_id: translated_track
            .as_ref()
            .map(|track| track.id.clone())
            .or_else(|| source_track.as_ref().map(|track| track.id.clone())),
        separation_backend: normalize_separation_backend(request.separation_backend.as_deref()),
        queue_export_pack: request.queue_export_pack,
        queue_qc: request.queue_qc,
        variant_label: None,
        tts_backend_id: Some(default_dub_backend_id(paths)),
        speaker_overrides: Vec::new(),
        speaker_count: request.speaker_count.clone(),
    };

    if let Some(track) = translated_track.clone() {
        let outcome = queue_localization_continuation_from_track(
            paths,
            &item,
            &track,
            pipeline.clone(),
            Some(batch_id.clone()),
        )?;
        return Ok(LocalizationRunQueueSummary {
            batch_id,
            item_id,
            title: item.title,
            stage: outcome.stage,
            source_track_id: outcome.source_track_id,
            translated_track_id: outcome.translated_track_id,
            queued_jobs: outcome.queued_jobs,
            notes: outcome.notes,
        });
    }

    if let Some(track) = source_track.clone() {
        let outcome = queue_localization_continuation_from_track(
            paths,
            &item,
            &track,
            pipeline.clone(),
            Some(batch_id.clone()),
        )?;
        return Ok(LocalizationRunQueueSummary {
            batch_id,
            item_id,
            title: item.title,
            stage: outcome.stage,
            source_track_id: outcome.source_track_id,
            translated_track_id: outcome.translated_track_id,
            queued_jobs: outcome.queued_jobs,
            notes: outcome.notes,
        });
    }

    let params_json = serde_json::to_string(&AsrLocalParams {
        item_id: item_id.clone(),
        lang,
        model_id: paths.effective_asr_model_id(),
        batch_on_import: false,
        pipeline: Some(pipeline),
    })?;
    let queued_job = enqueue_with_type_item_and_batch_id(
        paths,
        JobType::AsrLocal,
        params_json,
        Some(item_id.clone()),
        Some(batch_id.clone()),
    )?;
    Ok(LocalizationRunQueueSummary {
        batch_id,
        item_id,
        title: item.title,
        stage: "asr".to_string(),
        source_track_id: None,
        translated_track_id: None,
        queued_jobs: vec![queued_job],
        notes: vec!["No subtitle track was available, so VoxVulgi queued ASR first.".to_string()],
    })
}

pub fn enqueue_experimental_backend_batch_v1(
    paths: &AppPaths,
    request: ExperimentalBackendBatchRequest,
) -> Result<ExperimentalBackendBatchQueueSummary> {
    let item_ids = normalize_localization_batch_item_ids(request.item_ids)?;
    if item_ids.is_empty() {
        return Err(EngineError::InstallFailed(
            "choose at least one item for experimental backend batch runs".to_string(),
        ));
    }
    let backend_ids = normalize_experimental_backend_batch_backend_ids(request.backend_ids)?;
    if backend_ids.is_empty() {
        return Err(EngineError::InstallFailed(
            "choose at least one experimental backend".to_string(),
        ));
    }
    let batch_id = Uuid::new_v4().to_string();
    let targets = resolve_experimental_backend_batch_targets(
        paths,
        &backend_ids,
        request.variant_label.as_deref(),
        &batch_id,
    )?;
    if targets.backends.is_empty() {
        return Err(EngineError::InstallFailed(
            "none of the selected experimental backends are ready; configure and probe them in Diagnostics first"
                .to_string(),
        ));
    }
    let separation_backend = normalize_separation_backend(request.separation_backend.as_deref());
    let mut items: Vec<ExperimentalBackendBatchItemResult> = Vec::new();

    for item_id in item_ids {
        let item = library::get_item_by_id(paths, &item_id)?;
        let selected_track = select_localization_batch_track(paths, &item_id)?;
        let track = match selected_track {
            Some(track) => track,
            None => {
                items.push(ExperimentalBackendBatchItemResult {
                    item_id: item_id.clone(),
                    title: item.title.clone(),
                    track_id: None,
                    queued_jobs: Vec::new(),
                    warnings: vec!["No subtitle track found for this item.".to_string()],
                });
                continue;
            }
        };
        let mut queued_jobs: Vec<JobRow> = Vec::new();
        for backend in &targets.backends {
            queued_jobs.push(enqueue_experimental_voice_backend_render_v1_with_batch_id(
                paths,
                item_id.clone(),
                track.id.clone(),
                backend.backend_id.clone(),
                backend.variant_label.clone(),
                request.auto_pipeline,
                separation_backend.clone(),
                request.queue_qc,
                request.queue_export_pack,
                Some(batch_id.clone()),
            )?);
        }
        items.push(ExperimentalBackendBatchItemResult {
            item_id,
            title: item.title,
            track_id: Some(track.id),
            queued_jobs,
            warnings: Vec::new(),
        });
    }

    let queued_jobs_total = items.iter().map(|item| item.queued_jobs.len()).sum();
    Ok(ExperimentalBackendBatchQueueSummary {
        batch_id,
        backend_ids: targets
            .backends
            .iter()
            .map(|value| value.backend_id.clone())
            .collect(),
        queued_jobs_total,
        warnings: targets.warnings,
        items,
    })
}

pub fn enqueue_voice_ab_preview_v1(
    paths: &AppPaths,
    request: VoiceAbPreviewRequest,
) -> Result<VoiceAbPreviewQueueSummary> {
    let item_id = request.item_id.trim().to_string();
    let source_track_id = request.source_track_id.trim().to_string();
    let speaker_key = request.speaker_key.trim().to_string();
    if item_id.is_empty() || source_track_id.is_empty() || speaker_key.is_empty() {
        return Err(EngineError::InstallFailed(
            "item_id, source_track_id, and speaker_key are required".to_string(),
        ));
    }

    let mut variant_a_label = normalize_variant_label(request.variant_a_label.as_deref())
        .unwrap_or_else(|| "a".to_string());
    let mut variant_b_label = normalize_variant_label(request.variant_b_label.as_deref())
        .unwrap_or_else(|| "b".to_string());
    if variant_a_label == variant_b_label {
        variant_b_label = format!("{variant_b_label}_2");
    }
    if variant_a_label == variant_b_label {
        variant_a_label = "a".to_string();
        variant_b_label = "b".to_string();
    }

    let mut override_a = request.variant_a_override;
    let mut override_b = request.variant_b_override;
    override_a.speaker_key = speaker_key.clone();
    override_b.speaker_key = speaker_key.clone();

    let batch_id = Uuid::new_v4().to_string();
    let separation_backend = normalize_separation_backend(request.separation_backend.as_deref());
    let mut queued_jobs: Vec<JobRow> = Vec::new();

    for (variant_label, override_value) in [
        (variant_a_label.clone(), override_a),
        (variant_b_label.clone(), override_b),
    ] {
        let params_json = serde_json::to_string(&DubVoicePreservingV1Params {
            item_id: item_id.clone(),
            source_track_id: source_track_id.clone(),
            batch_on_import: false,
            pipeline: Some(LocalizationPipelineOptions {
                auto_pipeline: true,
                output_mode: Some("dub".to_string()),
                source_track_id: Some(source_track_id.clone()),
                separation_backend: separation_backend.clone(),
                queue_export_pack: request.queue_export_pack,
                queue_qc: request.queue_qc,
                variant_label: Some(variant_label),
                tts_backend_id: Some(default_dub_backend_id(paths)),
                speaker_overrides: vec![override_value],
                speaker_count: DiarizationSpeakerCountRequest::default(),
            }),
        })?;
        queued_jobs.push(enqueue_with_type_item_and_batch_id(
            paths,
            JobType::DubVoicePreservingV1,
            params_json,
            Some(item_id.clone()),
            Some(batch_id.clone()),
        )?);
    }

    Ok(VoiceAbPreviewQueueSummary {
        batch_id,
        variant_a_label,
        variant_b_label,
        queued_jobs,
    })
}

